const job = $item(0).$node['Lay draft da duyet tu PostgreSQL'].json;
const response = $json;
const statusCode = Number(response.statusCode || response.status || 200);
const retryable = [429, 500, 502, 503, 504].includes(statusCode);
const attempts = Number(job.attempts || 0) + 1;
const deadLetter = Boolean(response.error) && (!retryable || attempts >= 3);
const status = response.error ? (deadLetter ? 'dead_letter' : 'retry_queued') : 'published';
const q = (v) => `'${String(v ?? '').replaceAll("'", "''")}'`;
const providerId = response.id || response.postId || response.data?.id || null;
const errorMessage = response.error?.message || response.message || null;
const errorCode = response.error?.code || statusCode;
const sql = status === 'published'
  ? `UPDATE publishing_jobs SET status='published', claimed_at=NULL, provider_post_id=${q(providerId)}, published_at=now(), attempts=attempts+1, last_error_code=NULL, last_error_message=NULL WHERE id=${q(job.publishing_job_id)} AND status='publishing'; INSERT INTO audit_events(entity_type,entity_id,event_type,actor_type,actor_id,payload_json) VALUES ('publishing_job',${q(job.publishing_job_id)},'published','system','n8n',${q(JSON.stringify({provider_id: providerId, idempotency_key: job.idempotency_key}))}::jsonb);`
  : `UPDATE publishing_jobs SET status=${q(deadLetter ? 'failed' : 'queued')}, claimed_at=NULL, attempts=attempts+1, last_error_code=${q(errorCode)}, last_error_message=${q(errorMessage)} WHERE id=${q(job.publishing_job_id)} AND status='publishing'; INSERT INTO audit_events(entity_type,entity_id,event_type,actor_type,actor_id,payload_json) VALUES ('publishing_job',${q(job.publishing_job_id)},${q(deadLetter ? 'dead_letter' : 'publish_retry')},'system','n8n',${q(JSON.stringify({error_code: errorCode, error_message: errorMessage, backoff_seconds: [30,120,600][Math.min(attempts-1,2)], idempotency_key: job.idempotency_key}))}::jsonb);`;
return [{json:{...job,...response,state_operation:'mark_job_'+status,state_sql:sql,status,attempts,retry_policy:{retryable:[429,500,502,503,504],max_attempts:3,backoff_seconds:[30,120,600]}}}];

